import ast
import json
import subprocess
from pathlib import Path
from typing import Any

import lizard
from cognitive_complexity.api import get_cognitive_complexity


def python_symbols(source: str) -> list[tuple[str, ast.FunctionDef | ast.AsyncFunctionDef]]:
    result: list[tuple[str, ast.FunctionDef | ast.AsyncFunctionDef]] = []

    def visit(node: ast.AST, scope: tuple[str, ...]) -> None:
        if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            scope = (*scope, node.name)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            result.append((".".join(scope), node))
        for child in ast.iter_child_nodes(node):
            visit(child, scope)

    visit(ast.parse(source), ())
    return result


def metrics(path: str, source: str) -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    lines = source.splitlines()
    symbols = python_symbols(source) if path.endswith(".py") else None
    for function in lizard.analyze_file.analyze_source_code(path, source).function_list:
        cognitive = None
        name = function.name
        if symbols is not None:
            candidates = [(qualified, node) for qualified, node in symbols
                          if function.start_line <= node.lineno <= function.end_line]
            if not candidates:
                raise RuntimeError(f"No Python symbol for {path}:{function.start_line}: {name}")
            name, node = min(candidates, key=lambda entry: entry[1].lineno)
            cognitive = get_cognitive_complexity(node)
        if name in result:
            # Native overloads keep their signature as the scientific symbol key.
            name = function.long_name
        result[name] = {
            "nloc": function.nloc,
            "cyclomatic": function.cyclomatic_complexity,
            "cognitive": cognitive,
            "parameters": function.parameter_count,
            "tokens": function.token_count,
            "physical_lines": function.end_line - function.start_line + 1,
            "start_line": function.start_line,
            "body": "\n".join(lines[function.start_line - 1:function.end_line]),
        }
    return result


inputs = json.loads(Path('.tmp/metal-native/complexity-inputs.json').read_text())
root = Path(inputs['root'])
records: list[dict[str, Any]] = []
baselines = {str(root): '13d0a3076', inputs['native_root']: '127ab63d0cab71320702e562703c4aaa0c6570d1'}
for directory, paths in ((root, inputs['python_files']), (Path(inputs['native_root']), inputs['native_files'])):
    for path in paths:
        previous = subprocess.run(['git', 'show', f'{baselines[str(directory)]}:{path}'], cwd=directory, capture_output=True, text=True, check=False)
        before = metrics(path, previous.stdout) if previous.returncode == 0 else {}
        after = metrics(path, (directory / path).read_text())
        for name, current in after.items():
            prior = before.get(name)
            if prior is not None and prior['body'] == current['body']:
                continue
            records.append({'file': path, 'symbol': name, 'before': None if prior is None else {key: value for key, value in prior.items() if key != 'body'}, 'after': {key: value for key, value in current.items() if key != 'body'}})
output = root / '.tmp/metal-native/evidence/complexity.json'
output.write_text(json.dumps({'tools': ['lizard 1.24.1', 'cognitive-complexity 1.3.0'], 'baselines': baselines, 'cognitive_scope': 'Python AST; C++ cognitive complexity is unavailable, not zero.', 'records': records}, sort_keys=True, indent=2) + '\n')
print(f'Measured {len(records)} touched symbols; evidence {output}')
for record in records:
    current = record['after']
    if current['cyclomatic'] > 40 or current['physical_lines'] > 200 or (current['cognitive'] is not None and current['cognitive'] > 50):
        print(record['file'], record['symbol'], 'before=', record['before'], 'after=', current)
